import { sql } from "drizzle-orm";
import {
  boolean,
  check,
  pgEnum,
  pgTable,
  serial,
  text,
  timestamp,
  integer,
  index,
  uniqueIndex,
  primaryKey,
} from "drizzle-orm/pg-core";

// Better Auth tables (user, session, account, verification) generated by its
// CLI (`pnpm exec better-auth generate`) and kept here so the schema stays in
// one place, as the source for `drizzle-kit generate`.
export const user = pgTable("user", {
  id: text("id").primaryKey(),
  name: text("name").notNull(),
  email: text("email").notNull().unique(),
  emailVerified: boolean("email_verified").default(false).notNull(),
  image: text("image"),
  createdAt: timestamp("created_at", { withTimezone: true })
    .notNull()
    .defaultNow(),
  updatedAt: timestamp("updated_at", { withTimezone: true })
    .notNull()
    .defaultNow()
    .$onUpdate(() => new Date()),
});

export const session = pgTable(
  "session",
  {
    id: text("id").primaryKey(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    token: text("token").notNull().unique(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .$onUpdate(() => new Date()),
    ipAddress: text("ip_address"),
    userAgent: text("user_agent"),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
  },
  (table) => ({
    userIdx: index("session_user_id_idx").on(table.userId),
  }),
);

export const account = pgTable(
  "account",
  {
    id: text("id").primaryKey(),
    accountId: text("account_id").notNull(),
    providerId: text("provider_id").notNull(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    accessToken: text("access_token"),
    refreshToken: text("refresh_token"),
    idToken: text("id_token"),
    accessTokenExpiresAt: timestamp("access_token_expires_at", {
      withTimezone: true,
    }),
    refreshTokenExpiresAt: timestamp("refresh_token_expires_at", {
      withTimezone: true,
    }),
    scope: text("scope"),
    password: text("password"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .$onUpdate(() => new Date()),
  },
  (table) => ({
    userIdx: index("account_user_id_idx").on(table.userId),
  }),
);

export const verification = pgTable(
  "verification",
  {
    id: text("id").primaryKey(),
    identifier: text("identifier").notNull(),
    value: text("value").notNull(),
    expiresAt: timestamp("expires_at", { withTimezone: true }).notNull(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
    updatedAt: timestamp("updated_at", { withTimezone: true })
      .notNull()
      .defaultNow()
      .$onUpdate(() => new Date()),
  },
  (table) => ({
    identifierIdx: index("verification_identifier_idx").on(table.identifier),
  }),
);

export type User = typeof user.$inferSelect;
export type Session = typeof session.$inferSelect;
export type Account = typeof account.$inferSelect;
export type Verification = typeof verification.$inferSelect;

// How often I want to talk to a contact; empty (null) means "not set"
export const contactFrequency = pgEnum("contact_frequency", [
  "weekly",
  "monthly",
  "quarterly",
  "yearly",
]);

export type ContactFrequency = (typeof contactFrequency.enumValues)[number];

// People I know personally
export const contacts = pgTable(
  "contacts",
  {
    id: serial("id").primaryKey(),
    // The user this contact belongs to; only its owner can see or change it.
    ownerId: text("owner_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    // How we know each other
    relationship: text("relationship"),
    phone: text("phone"),
    email: text("email"),
    frequency: contactFrequency("frequency"),
    // Optional date of birth. Day and month are always set together (one is the
    // birthday); the year is optional on its own (many people only know the
    // day and month). Day-in-month validity (no 31 Apr) is checked in the
    // server action; this table only guards the ranges and the pairing below.
    birthDay: integer("birth_day"),
    birthMonth: integer("birth_month"),
    birthYear: integer("birth_year"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => ({
    nameIdx: index("contacts_name_idx").on(table.name),
    ownerIdx: index("contacts_owner_id_idx").on(table.ownerId),
    birthdayValid: check(
      "contacts_birthday_valid",
      sql`(${table.birthDay} is null) = (${table.birthMonth} is null)
        and (${table.birthYear} is null or ${table.birthDay} is not null)
        and (${table.birthDay} is null or ${table.birthDay} between 1 and 31)
        and (${table.birthMonth} is null or ${table.birthMonth} between 1 and 12)
        and (${table.birthYear} is null or ${table.birthYear} between 1900 and 2100)`,
    ),
  }),
);

// Notes appended to a contact after talking to them
export const notes = pgTable(
  "notes",
  {
    id: serial("id").primaryKey(),
    contactId: integer("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    // Empty (null) body means "we talked" without any details
    body: text("body"),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => ({
    contactIdx: index("notes_contact_id_idx").on(table.contactId),
  }),
);

// Labels the owner sorts contacts into (family, friends, tennis, …)
export const groups = pgTable(
  "groups",
  {
    id: serial("id").primaryKey(),
    // The user this group belongs to; names are unique per owner, not globally.
    ownerId: text("owner_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    name: text("name").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => ({
    // Unique per owner, case-insensitive and folding "ё" into "е" — the same
    // normalization used for contact search, so "Теннис"/"теннис"/"тённис"
    // all count as one group for the same owner; different owners can each
    // have their own "Теннис".
    ownerNameUniqueIdx: uniqueIndex("groups_owner_id_name_unique_idx").on(
      table.ownerId,
      sql`translate(lower(${table.name}), 'ё', 'е')`,
    ),
  }),
);

// One row per magic-link email actually sent, used only to enforce "at most 3
// per address per 10 minutes" (see src/lib/magic-link-limit.ts). Separate from
// Better Auth's own `verification` table so purging stale links there (a new
// link revokes older ones) never disturbs this request history.
export const magicLinkRequests = pgTable(
  "magic_link_requests",
  {
    id: serial("id").primaryKey(),
    email: text("email").notNull(),
    createdAt: timestamp("created_at", { withTimezone: true })
      .notNull()
      .defaultNow(),
  },
  (table) => ({
    emailCreatedAtIdx: index("magic_link_requests_email_created_at_idx").on(
      table.email,
      table.createdAt,
    ),
  }),
);

// Which contact belongs to which group (many-to-many)
export const contactGroups = pgTable(
  "contact_groups",
  {
    contactId: integer("contact_id")
      .notNull()
      .references(() => contacts.id, { onDelete: "cascade" }),
    groupId: integer("group_id")
      .notNull()
      .references(() => groups.id, { onDelete: "cascade" }),
  },
  (table) => ({
    pk: primaryKey({ columns: [table.contactId, table.groupId] }),
    groupIdx: index("contact_groups_group_id_idx").on(table.groupId),
  }),
);

export type Contact = typeof contacts.$inferSelect;
export type NewContact = typeof contacts.$inferInsert;
export type Note = typeof notes.$inferSelect;
export type NewNote = typeof notes.$inferInsert;
export type Group = typeof groups.$inferSelect;
export type NewGroup = typeof groups.$inferInsert;
